local k={165,200,121,3,85,33,120,51,212,203,6,75,2,41,223,219,78,21,174,166,188,100,195,30,212,95,129,96,224,232,172,7}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
